      SUBROUTINE THRED1(RA,COR)CC     FIRST-ORDER ADVANCEMENT OF BEAM CENTROIDCC ----------------------------------------------------------------------C     LOCAL VARIABLESC      REAL          COR(6), COT(6), RA(6,6)C ----------------------------------------------------------------------CC     TRANSFORMATION OF BEAM CENTROIDC   50 DO 70 J = 1, 6      SS = 0.0      DO 60 K = 1, 6      SS = SS + RA(J,K)*COR(K)   60 CONTINUE      COT(J) = SS   70 CONTINUECC     RESET OFF-AXIS BEAM CENTROIDC  200 DO 220 J = 1, 6  220 COR(J) = COT(J)      RETURN      END